<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import { api, errorMessage } from '../../services/api';
import { useAuthStore } from '../../stores/auth';
import { bdt } from './types';
import { date } from '../../utils/format';
import AppTable from '../../components/tables/AppTable.vue';
import AppButton from '../../components/ui/AppButton.vue';
import AppInput from '../../components/ui/AppInput.vue';
import AppModal from '../../components/modals/AppModal.vue';
interface Product { id: string; principal: string; outstanding: string; installmentAmount?: string; installmentCount?: number; nextDueDate?: string; profit?: string; principalReturned?: string; title?: string; counterparty?: string; status: string; member?: { fullName: string; memberNo: string }; installments?: { number: number; dueDate: string; amount: string; paid: string; outstanding: string; status: string }[]; history?: { id: string; transactionNo: string; type: string; amount: string; effectiveDate: string }[]; }
interface Bank { id: string; name: string; code: string; kind: string; opening: string; deposits: string; withdrawals: string; closing: string; }
const props = defineProps<{ kind: 'loans' | 'investments' | 'bank'; own?: boolean; memberId?: string; refresh?: number }>();
const emit = defineEmits<{ entry: [value: { type: string; loanId?: string; investmentId?: string; label?: string }] }>();
const auth = useAuthStore(); const items = ref<Product[]>([]); const banks = ref<Bank[]>([]); const total = ref(0); const page = ref(1); const pages = ref(1); const loading = ref(false); const error = ref(''); const from = ref(''); const to = ref(''); const selected = ref<Product>();
const loanColumns = computed(() => [{ key: 'member', label: 'Member' }, { key: 'principal', label: 'Loan amount' }, { key: 'outstanding', label: 'Outstanding' }, { key: 'installmentAmount', label: 'Monthly installment' }, { key: 'nextDueDate', label: 'Next due' }, { key: 'status', label: 'Status' }, { key: 'actions', label: 'Actions' }].filter(column => !props.own || column.key !== 'member'));
const investmentColumns = [{ key: 'title', label: 'Investment' }, { key: 'principal', label: 'Invested' }, { key: 'principalReturned', label: 'Principal returned' }, { key: 'profit', label: 'Profit received' }, { key: 'outstanding', label: 'Outstanding' }, { key: 'status', label: 'Status' }, { key: 'actions', label: 'Actions' }];
let sequence = 0;
async function load(value = 1) {
  const request = ++sequence; loading.value = true; error.value = ''; page.value = value;
  try {
    const endpoint = props.kind === 'bank' ? '/finance/bank-summary' : `/finance/${props.kind}${props.own ? '/me' : ''}`;
    const { data } = await api.get(endpoint, { params: { ...(props.kind === 'bank' ? { from: from.value || undefined, to: to.value || undefined } : { page: value, pageSize: 20, memberId: props.memberId }) } });
    if (request !== sequence) return;
    if (props.kind === 'bank') banks.value = data.items;
    else { items.value = data.items; total.value = data.total; pages.value = data.pages; }
  } catch (e) { if (request === sequence) error.value = errorMessage(e); } finally { if (request === sequence) loading.value = false; }
}
async function detail(id: string) { error.value = ''; try { selected.value = (await api.get(`/finance/${props.kind}${props.own ? '/me' : ''}/${id}`)).data; } catch (e) { error.value = errorMessage(e); } }
watch(() => [props.kind, props.refresh, props.memberId], () => load()); onMounted(() => load());
</script>
<template>
  <section class="panel finance-statement product-report">
    <div class="panel-heading"><div><h2>{{ kind === 'loans' ? (own ? 'My loans' : 'Loans') : kind === 'investments' ? 'Investments & returns' : 'Cash & bank summary' }}</h2><p>{{ kind === 'loans' ? 'Approved principal, monthly installments and repayments.' : kind === 'investments' ? 'Approved investment principal and realized profit.' : 'Opening balance + deposits − withdrawals = closing balance.' }}</p></div><AppButton v-if="!own && !memberId && auth.can('finance.write')" @click="emit('entry', { type: kind === 'loans' ? 'LOAN_DISBURSEMENT' : kind === 'investments' ? 'INVESTMENT_PURCHASE' : 'TRANSFER' })">{{ kind === 'loans' ? 'New loan' : kind === 'investments' ? 'New investment' : 'Transfer funds' }}</AppButton></div>
    <div v-if="error" class="alert error" role="alert">{{ error }} <AppButton variant="ghost" @click="load()">Retry</AppButton></div>
    <template v-if="kind === 'bank'"><form class="finance-filters" @submit.prevent="load()"><AppInput v-model="from" label="From date" type="date" /><AppInput v-model="to" label="To date" type="date" /><AppButton type="submit" variant="secondary">Apply dates</AppButton></form><AppTable :rows="banks" :columns="[{key:'name',label:'Account'},{key:'opening',label:'Opening'},{key:'deposits',label:'Deposits / in'},{key:'withdrawals',label:'Withdrawals / out'},{key:'closing',label:'Closing'}]" :loading="loading"><template #cell-name="{ row }"><strong>{{ row.name }}</strong><small class="finance-cell-note">{{ row.code }} · {{ row.kind }}</small></template><template #cell-opening="{ row }">{{ bdt(row.opening) }}</template><template #cell-deposits="{ row }">{{ bdt(row.deposits) }}</template><template #cell-withdrawals="{ row }">{{ bdt(row.withdrawals) }}</template><template #cell-closing="{ row }"><strong>{{ bdt(row.closing) }}</strong></template></AppTable></template>
    <AppTable v-else :rows="items" :columns="kind === 'loans' ? loanColumns : investmentColumns" :page="page" :pages="pages" :total="total" :loading="loading" @page="load"><template #cell-member="{ row }">{{ row.member?.fullName }}<small class="finance-cell-note">{{ row.member?.memberNo }}</small></template><template #cell-title="{ row }"><strong>{{ row.title }}</strong><small class="finance-cell-note">{{ row.counterparty }}</small></template><template #cell-principal="{ row }">{{ bdt(row.principal) }}</template><template #cell-installmentAmount="{ row }">{{ bdt(row.installmentAmount!) }}<small class="finance-cell-note">{{ row.installmentCount }} installments; final amount may differ by cents</small></template><template #cell-outstanding="{ row }">{{ bdt(row.outstanding) }}</template><template #cell-principalReturned="{ row }">{{ bdt(row.principalReturned!) }}</template><template #cell-profit="{ row }">{{ bdt(row.profit!) }}</template><template #cell-nextDueDate="{ row }">{{ row.nextDueDate ? date(row.nextDueDate) : '—' }}</template><template #cell-actions="{ row }"><div class="button-row"><AppButton variant="ghost" @click="detail(row.id)">View history</AppButton><AppButton v-if="!own && auth.can('finance.write') && row.status !== 'CANCELLED' && (kind === 'investments' || row.outstanding !== '0.00')" variant="secondary" @click="emit('entry', {type: kind === 'loans' ? 'LOAN_REPAYMENT' : 'INVESTMENT_RETURN', loanId: kind === 'loans' ? row.id : undefined, investmentId: kind === 'investments' ? row.id : undefined, label: row.title || row.member?.fullName})">{{ kind === 'loans' ? 'Repay' : 'Record return' }}</AppButton></div></template><template #empty>No approved {{ kind }} yet. Pending requests appear in Finance → Transactions.</template></AppTable>
    <AppModal :open="!!selected" :title="kind === 'loans' ? 'Loan schedule & history' : 'Investment history'" size="wide" @close="selected = undefined"><template v-if="selected"><div class="finance-detail-heading"><h2>{{ selected.title || selected.member?.fullName }}</h2><strong>Outstanding {{ bdt(selected.outstanding) }}</strong></div><p v-if="kind === 'loans'" class="muted">Principal-only monthly schedule. Repayments are allocated to the earliest unpaid installment.</p><AppTable v-if="selected.installments" :rows="selected.installments.map(r => ({...r,id:String(r.number)}))" :columns="[{key:'number',label:'#'},{key:'dueDate',label:'Due date'},{key:'amount',label:'Due'},{key:'paid',label:'Paid'},{key:'outstanding',label:'Remaining'},{key:'status',label:'Status'}]"><template #cell-amount="{ row }">{{ bdt(row.amount) }}</template><template #cell-paid="{ row }">{{ bdt(row.paid) }}</template><template #cell-outstanding="{ row }">{{ bdt(row.outstanding) }}</template></AppTable><h3 class="product-history-heading">Posted transactions</h3><AppTable :rows="selected.history ?? []" :columns="[{key:'effectiveDate',label:'Date'},{key:'transactionNo',label:'Transaction'},{key:'type',label:'Type'},{key:'amount',label:'Amount'}]"><template #cell-effectiveDate="{ row }">{{ date(row.effectiveDate) }}</template><template #cell-amount="{ row }">{{ bdt(row.amount) }}</template></AppTable></template></AppModal>
  </section>
</template>
